export function sortList(values          )           {
function sort(a         )         {if(a.length<2)return a;const mid=Math.floor(a.length/2),l=sort(a.slice(0,mid)),r=sort(a.slice(mid)),out         =[];let i=0,j=0;while(i<l.length&&j<r.length)out.push(l[i]<=r[j]?l[i++]:r[j++]);return out.concat(l.slice(i),r.slice(j));}return sort([...values]);
}

